-- Create "notifications" table
CREATE TABLE "public"."notifications" ("id" uuid NOT NULL, "recipient_user_id" uuid NOT NULL, "actor_user_id" uuid NOT NULL, "actor_profile_id" uuid NOT NULL, "type" character varying(20) NOT NULL, "server_id" uuid NOT NULL, "post_id" uuid NULL, "comment_id" uuid NULL, "read_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" uuid NOT NULL, "updated_by" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "notifications_actor_profile_id_fkey" FOREIGN KEY ("actor_profile_id") REFERENCES "public"."server_member_profiles" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "notifications_actor_user_id_fkey" FOREIGN KEY ("actor_user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "notifications_comment_id_fkey" FOREIGN KEY ("comment_id") REFERENCES "public"."server_post_comments" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "notifications_post_id_fkey" FOREIGN KEY ("post_id") REFERENCES "public"."server_posts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "notifications_recipient_user_id_fkey" FOREIGN KEY ("recipient_user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "notifications_server_id_fkey" FOREIGN KEY ("server_id") REFERENCES "public"."servers" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_notifications_pk_01" to table: "notifications"
CREATE INDEX "idx_notifications_pk_01" ON "public"."notifications" ("recipient_user_id", "created_at" DESC);
-- Create index "idx_notifications_pk_02" to table: "notifications"
CREATE INDEX "idx_notifications_pk_02" ON "public"."notifications" ("recipient_user_id") WHERE (read_at IS NULL);
